assert_true "compose Darwin+Colima absent: logs skipped device" \
    grep -qF "skipping device ${DARWIN_DEV} (not found on this host)" "${TMP}/cb/darwin-absent.log"
mv "${TMP}/cb/config.full.json" "${TMP}/cb/config.json"
assert_true "compose: missing override file left out" bash -c "! grep -q compose.local.yaml '${TMP}/cb/docker.log'"
rm -f "${TMP}/cb/docker.log"
assert_eq "compose: base image built from the service" "t" "$(cl '_build_base_image t' 2>/dev/null)"
assert_true "compose: docker build arguments" grep -qxF \
    "build -f ${REPO}/.devcontainer/Dockerfile.dev --target dev -t t --build-arg V=1 ${REPO}/.devcontainer" "${TMP}/cb/docker.log"
tag1="$(cl image_tag)"
assert_true "compose: image tag" grep -qE '^orca-devcontainer-fixture-repo:[0-9a-f]{12}$' <<<"$tag1"
mkdir -p "${REPO}/.devcontainer/.generated"
echo "per start" >"${REPO}/.devcontainer/.generated/compose.local.yaml"
assert_eq "compose: image tag ignores .generated/" "$tag1" "$(cl image_tag)"
assert_eq "compose: built service has no prebuilt base" "" "$(cl prebuilt_base_image)"

# A prebuilt image can retain its name while initializeCommand replaces it.
jq '.services.dev |= (del(.build) + {image: "fixture-base"})' \
    "${TMP}/cb/config.json" >"${TMP}/cb/prebuilt.json"
mv "${TMP}/cb/prebuilt.json" "${TMP}/cb/config.json"
assert_eq "compose: image-only service is a prebuilt base" "fixture-base" "$(cl prebuilt_base_image)"
printf 'sha256:first\n' >"${TMP}/cb/base-id"
tag1="$(cl image_tag)"
printf 'sha256:second\n' >"${TMP}/cb/base-id"
tag2="$(cl image_tag)"
assert_true "compose: new base ID changes the Orca tag" test "$tag1" != "$tag2"
cat >"${REPO}/.devcontainer/initialize-fixture.sh" <<EOF
printf 'sha256:second\n' >"${TMP}/cb/base-id"
echo 'host hook output'
EOF
jq '.initializeCommand = "bash .devcontainer/initialize-fixture.sh"' \
