# --- locks -------------------------------------------------------------------------
assert_eq "lock: acquire and release" "held:gone" \
    "$(lib 'lock_acquire t 5; [ -d "$LOCK_DIR/t.lock" ] && printf held; lock_release t; [ -d "$LOCK_DIR/t.lock" ] || printf :gone')"
assert_eq "lock: released on exit" "gone" \
    "$(lib 'lock_acquire t2 5; exit 0'; [ -d "${TMP}/state/locks/t2.lock" ] && echo held || echo gone)"
assert_eq "lock: kept across subshells" "held" \
    "$(lib 'lock_acquire t5 5; (true); x=$(echo); [ -d "$LOCK_DIR/t5.lock" ] && echo held')"
mkdir -p "${TMP}/state/locks/t3.lock"
echo 999999 >"${TMP}/state/locks/t3.lock/pid"
assert_eq "lock: stale lock taken over" "ok" "$(lib 'lock_acquire t3 5 2>/dev/null; printf ok')"
lib 'lock_acquire t4 5; sleep 3' &
sleep 1
assert_true "lock: second holder times out" lib_fails 'lock_acquire t4 1'
wait

# --- known_hosts -------------------------------------------------------------------
mkdir -p "${TMP}/home/.ssh"
k1="$(ssh-keygen -q -t ed25519 -N '' -f "${TMP}/k1" && awk '{print $1" "$2}' "${TMP}/k1.pub")"
k2="$(ssh-keygen -q -t ed25519 -N '' -f "${TMP}/k2" && awk '{print $1" "$2}' "${TMP}/k2.pub")"
printf 'example.com %s\n' "$k1" >"${TMP}/home/.ssh/known_hosts"
echo "users backup" >"${TMP}/home/.ssh/known_hosts.old"
lib "record_known_host 2222 '$k1'; record_known_host 2222 '$k2'"
assert_eq "known_hosts: one entry per endpoint in the user file" "1" \
    "$(grep -c '^\[127.0.0.1\]:2222 ' "${TMP}/home/.ssh/known_hosts")"
assert_true "known_hosts: latest key recorded" grep -qxF "[127.0.0.1]:2222 ${k2}" "${TMP}/home/.ssh/known_hosts"
assert_true "known_hosts: script file recorded" grep -qxF "[127.0.0.1]:2222 ${k2}" "${TMP}/state/known_hosts"
assert_true "known_hosts: other entries kept" grep -q '^example.com ' "${TMP}/home/.ssh/known_hosts"
assert_eq "known_hosts: user's .old preserved" "users backup" "$(cat "${TMP}/home/.ssh/known_hosts.old")"
lib "forget_known_host 2222 '$k1'"
assert_true "known_hosts: forget with another key keeps entry" grep -q '^\[127.0.0.1\]:2222 ' "${TMP}/home/.ssh/known_hosts"
lib "forget_known_host 2222 '$k2'"
assert_true "known_hosts: forget removes user entry" bash -c "! grep -q '^\[127.0.0.1\]:2222 ' '${TMP}/home/.ssh/known_hosts'"
assert_true "known_hosts: forget removes script entry" bash -c "! grep -q '^\[127.0.0.1\]:2222 ' '${TMP}/state/known_hosts'"
assert_eq "known_hosts: user's .old still preserved" "users backup" "$(cat "${TMP}/home/.ssh/known_hosts.old")"

# --- ensure_ssh_key ------------------------------------------------------------------
mkdir -p "${TMP}/legacy"
cp "${TMP}/k1" "${TMP}/legacy/id_ed25519"
cp "${TMP}/k1.pub" "${TMP}/legacy/id_ed25519.pub"
lib "LEGACY_SSH_KEY='${TMP}/legacy/id_ed25519'; ensure_ssh_key" 2>/dev/null
assert_true "ssh key: legacy key moved to the state directory" cmp -s "${TMP}/k1" "${TMP}/state/id_ed25519"
# Git Bash copies instead of linking and has no Unix modes; the legacy
# location only ever existed on macOS.
if ! $IS_WINDOWS; then
    assert_true "ssh key: legacy path is a symlink" test -L "${TMP}/legacy/id_ed25519"
    assert_true "ssh key: legacy symlink resolves" cmp -s "${TMP}/k1" "${TMP}/legacy/id_ed25519"
    assert_eq "ssh key: state directory is private" "700" "$(stat -c %a "${TMP}/state" 2>/dev/null || stat -f %Lp "${TMP}/state")"
fi
rm -rf "${TMP}/state/id_ed25519"*
lib "LEGACY_SSH_KEY='${TMP}/none'; ensure_ssh_key" 2>/dev/null
assert_true "ssh key: generated when none exists" test -f "${TMP}/state/id_ed25519.pub"
assert_true "ssh key: nothing written into the repository" test ! -e "${REPO}/scripts/orca-vm/.ssh"

# --- link-agent-auth.sh -------------------------------------------------------------
# Runs inside the Linux containers only; Git Bash copies instead of linking.
if $IS_WINDOWS; then
    echo "skipped: link-agent-auth.sh (needs real symlinks; runs in the Linux containers)"
elif [ -f "$LINK_AUTH_SRC" ]; then
    auth() { AGENT_AUTH_HOME="${TMP}/auth" CLAUDE_CONFIG_DIR="${TMP}/auth/.claude" bash "$LINK_AUTH_SRC" >/dev/null; }
    mkdir -p "${TMP}/auth/.codex-host" "${TMP}/auth/.codex" "${TMP}/auth/.claude-host" "${TMP}/auth/.opencode-host"
    echo shared >"${TMP}/auth/.codex-host/auth.json"
    echo 'model = "o3"' >"${TMP}/auth/.codex-host/config.toml"
    ln -s "${TMP}/auth/.codex-host/auth.json" "${TMP}/auth/.codex/auth.json"
    auth
    assert_true "auth: legacy codex shared link removed" \
        test ! -e "${TMP}/auth/.codex/auth.json" -a ! -L "${TMP}/auth/.codex/auth.json"
    assert_true "auth: codex config seeded as copy" \
        test -f "${TMP}/auth/.codex/config.toml" -a ! -L "${TMP}/auth/.codex/config.toml"
    assert_eq "auth: codex config content seeded" 'model = "o3"' "$(cat "${TMP}/auth/.codex/config.toml")"
    echo local >"${TMP}/auth/.codex/auth.json"
    echo 'model = "local"' >"${TMP}/auth/.codex/config.toml"
    auth
    assert_eq "auth: container codex login kept" "local" "$(cat "${TMP}/auth/.codex/auth.json")"
    assert_eq "auth: existing codex config kept" 'model = "local"' "$(cat "${TMP}/auth/.codex/config.toml")"
    echo '{"a":1}' >"${TMP}/auth/.claude-host/.claude.json"
    echo creds >"${TMP}/auth/.claude-host/.credentials.json"
    echo '{"source":"host"}' >"${TMP}/auth/.claude-host/settings.json"
    mkdir -p "${TMP}/auth/.claude"
    ln -s "${TMP}/auth/.claude-host/.credentials.json" "${TMP}/auth/.claude/.credentials.json"
    auth
    assert_true "auth: legacy claude credentials link removed" \
        test ! -e "${TMP}/auth/.claude/.credentials.json" -a ! -L "${TMP}/auth/.claude/.credentials.json"
    assert_true "auth: claude state seeded as copy" test -f "${TMP}/auth/.claude/.claude.json" -a ! -L "${TMP}/auth/.claude/.claude.json"
    assert_eq "auth: claude settings seeded" '{"source":"host"}' "$(cat "${TMP}/auth/.claude/settings.json")"
    echo own >"${TMP}/auth/.claude/.credentials.json"
    echo '{"source":"orca"}' >"${TMP}/auth/.claude/settings.json"
    auth
    assert_eq "auth: existing claude login kept" "own" "$(cat "${TMP}/auth/.claude/.credentials.json")"
    assert_eq "auth: existing claude settings kept" '{"source":"orca"}' "$(cat "${TMP}/auth/.claude/settings.json")"
    assert_true "auth: absent opencode login skipped" test ! -e "${TMP}/auth/.local/share/opencode"
    echo oc_shared >"${TMP}/auth/.opencode-host/auth.json"
    auth
    assert_true "auth: opencode login linked" test -L "${TMP}/auth/.local/share/opencode/auth.json"
    rm "${TMP}/auth/.opencode-host/auth.json"
    auth
    assert_true "auth: dangling opencode link removed" \
        test ! -e "${TMP}/auth/.local/share/opencode/auth.json" -a ! -L "${TMP}/auth/.local/share/opencode/auth.json"
else
    fail "link-agent-auth.sh not found at ${LINK_AUTH_SRC}"
fi

# --- share_opencode_auth ----------------------------------------------------------------
mkdir -p "${TMP}/oc/bin"
cat >"${TMP}/oc/bin/opencode" <<'EOF'
#!/bin/sh
[ "$1 $2" = "auth export" ] || exit 2
case "${3:-}" in
    github-copilot) echo '[{"integrationID":"github-copilot","value":{"refresh":"secret"}}]' ;;
    '') echo '[{"integrationID":"github-copilot","value":{"refresh":"secret"}},{"integrationID":"anthropic","value":{"key":"secret2"}}]' ;;
    *) echo "Integration not found: $3" >&2; exit 1 ;;
esac
EOF
cat >"${TMP}/oc/bin/docker" <<EOF
#!/bin/sh
printf '%s\n' "\$*" >>"${TMP}/oc/docker.args"
cat >>"${TMP}/oc/docker.stdin"
exit \${DOCKER_STUB_RC:-0}
EOF
chmod +x "${TMP}/oc/bin/opencode" "${TMP}/oc/bin/docker"
oc() { lib "PATH='${TMP_PATH}/oc/bin':\$PATH; share_opencode_auth c1" 2>"${TMP}/oc/log"; }
oc
assert_true "opencode auth: imported as remoteUser" grep -q '^exec -u root -i c1 sh -c ' "${TMP}/oc/docker.args"
assert_true "opencode auth: runs auth import" grep -q 'auth import' "${TMP}/oc/docker.args"
assert_true "opencode auth: falls back to ~/.opencode/bin" grep -qF '$HOME/.opencode/bin/opencode' "${TMP}/oc/docker.args"
assert_true "opencode auth: exported credentials piped" grep -q '"github-copilot"' "${TMP}/oc/docker.stdin"
assert_true "opencode auth: only the default integration" bash -c "! grep -q anthropic '${TMP}/oc/docker.stdin'"
assert_true "opencode auth: secret not logged" bash -c "! grep -q secret '${TMP}/oc/log'"
rm -f "${TMP}/oc/docker."*
ORCA_DOCKER_OPENCODE_AUTH="all" oc
assert_true "opencode auth: all exports every login" grep -q anthropic "${TMP}/oc/docker.stdin"
assert_eq "opencode auth: all imports once" "1" "$(wc -l <"${TMP}/oc/docker.args" | tr -d ' ')"
rm -f "${TMP}/oc/docker."*
ORCA_DOCKER_OPENCODE_AUTH="other" oc
assert_true "opencode auth: missing host login skipped" test ! -e "${TMP}/oc/docker.args"
ORCA_DOCKER_OPENCODE_AUTH="none" oc
assert_true "opencode auth: none disables" test ! -e "${TMP}/oc/docker.args"
ORCA_DOCKER_OPENCODE_AUTH="github-copilot other2" DOCKER_STUB_RC=127 oc
assert_true "opencode auth: no opencode in the container is logged" grep -q 'no opencode in the container' "${TMP}/oc/log"
assert_true "opencode auth: no host opencode is not an error" \
    lib "host_opencode() { return 1; }; share_opencode_auth c1 2>/dev/null"

# --- share_github_auth -------------------------------------------
# The docker stub runs the container-side script locally with a fake container
# home and a fake gh; the host gh is stubbed too.
GC="${TMP}/gc"
mkdir -p "${GC}/bin" "${GC}/cbin"
GC_PATH="${TMP_PATH}/gc"
cat >"${GC}/bin/docker" <<EOF
#!/bin/sh
printf '%s\n' "\$*" >>"${GC}/docker.args"
[ "\$1" = exec ] || exit 1
shift 5 # exec -u <user> -i <name>
HOME="${GC}/ctr" PATH="${GC_PATH}/cbin:\$PATH" exec "\$@"
EOF
cat >"${GC}/bin/gh" <<'EOF'
#!/bin/sh
[ "$1 $2" = "auth token" ] && [ -n "${HOST_TOKEN:-}" ] && { echo "$HOST_TOKEN"; exit 0; }
exit 1
EOF
cat >"${GC}/cbin/gh" <<'EOF'
#!/bin/sh
f="$HOME/gh-token"
case "$1 $2" in
    "auth status") [ ! -s "$f" ] || echo fixture ;;
    "auth token") [ -s "$f" ] && cat "$f" || exit 1 ;;
    "auth login") cat >"$f" ;;
    "auth logout") rm -f "$f" ;;
    "auth setup-git") echo setup >>"$HOME/gh-setup" ;;
    *) exit 2 ;;
esac
EOF
chmod +x "${GC}/bin/"* "${GC}/cbin/"*
gc() { # snippet
    lib "PATH='${GC_PATH}/bin':\$PATH; $1" 2>>"${GC}/log"
}
reset_ctr() { rm -rf "${GC}/ctr" "${GC}/log" "${GC}/docker.args"; mkdir -p "${GC}/ctr"; }
ctr_git() { HOME="${GC}/ctr" git config --global --get-all url.https://github.com/.insteadOf 2>/dev/null; }

# curl stub for the scope check: answers with SCOPES, logs its arguments.
cat >"${GC}/bin/curl" <<'EOF'
#!/bin/sh
printf '%s\n' "$*" >>"${GC_LOG_DIR}/curl.args"
grep -q '^header = "Authorization: token ' || exit 22
printf 'HTTP/2 200\r\nx-oauth-scopes: %s\r\n\r\n' "${SCOPES:-}"
EOF
chmod +x "${GC}/bin/curl"
export GC_LOG_DIR="$GC"
TOKEN_FILE="${TMP}/state/github-token"
mkdir -p "${TMP}/state"
host_mode() { HOST_TOKEN="$1" ORCA_DOCKER_GITHUB_AUTH="${2:-host}" gc 'share_github_auth c1'; }

# Default: no token file, no token, even with a host gh login.
reset_ctr
rm -f "$TOKEN_FILE"
HOST_TOKEN=gho_hosttoken gc 'share_github_auth c1'
assert_true "github auth: default shares no host login" test ! -e "${GC}/ctr/gh-token"
assert_true "github auth: default hint names the token file" grep -qF "$TOKEN_FILE" "${GC}/log"
assert_true "github auth: default hint names the opt-in" grep -q 'ORCA_DOCKER_GITHUB_AUTH=host' "${GC}/log"
assert_true "github auth: default without token warns about nothing" bash -c "! grep -q WARNING '${GC}/log'"

# Default with a token file: shared, no warning.
reset_ctr
printf 'github_pat_scoped\r\n' >"$TOKEN_FILE"
chmod 600 "$TOKEN_FILE"
: >"${GC}/curl.args"
HOST_TOKEN=gho_hosttoken gc 'share_github_auth c1'
assert_eq "github auth: token file logged in (CR stripped)" "github_pat_scoped" "$(cat "${GC}/ctr/gh-token" 2>/dev/null)"
assert_true "github auth: gh is the git credential helper" test -s "${GC}/ctr/gh-setup"
assert_eq "github auth: SSH remotes rewritten to HTTPS" "git@github.com:|ssh://git@github.com/" "$(ctr_git | paste -sd'|' -)"
assert_true "github auth: token file shared without a warning" bash -c "! grep -q WARNING '${GC}/log'"
assert_true "github auth: fine-grained token not scope-checked" test ! -s "${GC}/curl.args"
assert_true "github auth: token file not logged" bash -c "! grep -q pat_scoped '${GC}/log'"
assert_true "github auth: token file not on the command line" bash -c "! grep -q pat_scoped '${GC}/docker.args'"
if ! $IS_WINDOWS; then
    chmod 644 "$TOKEN_FILE"
    gc 'share_github_auth c1'
    assert_true "github auth: readable token file warned about" grep -q 'open to other users' "${GC}/log"
    chmod 600 "$TOKEN_FILE"
fi
gc 'share_github_auth c1'
assert_eq "github auth: rewrite added once" "2" "$(ctr_git | wc -l | tr -d ' ')"
printf 'ghp_classic\n' >"$TOKEN_FILE"
SCOPES="repo, delete_repo" gc 'share_github_auth c1'
assert_eq "github auth: rotated token file replaces the shared login" "ghp_classic" "$(cat "${GC}/ctr/gh-token")"
assert_true "github auth: risky scope of a classic token warned about" grep -q 'scopes delete_repo;' "${GC}/log"
assert_true "github auth: token not on the curl command line" bash -c "! grep -q ghp_classic '${GC}/curl.args'"
printf 'bad token; x\n' >"$TOKEN_FILE"
gc 'share_github_auth c1'
assert_true "github auth: malformed token file removes the shared login" test ! -e "${GC}/ctr/gh-token"
assert_true "github auth: malformed token file reported" grep -q 'unexpected characters' "${GC}/log"
printf 'github_pat_scoped\n' >"$TOKEN_FILE"
gc 'share_github_auth c1'
rm -f "$TOKEN_FILE"
gc 'share_github_auth c1'
assert_true "github auth: removed token file removes the shared login" test ! -e "${GC}/ctr/gh-token"
assert_eq "github auth: removed token file removes the rewrite" "" "$(ctr_git)"
ORCA_DOCKER_GITHUB_TOKEN_FILE="${TMP}/elsewhere" gc 'share_github_auth c1'
assert_true "github auth: ORCA_DOCKER_GITHUB_TOKEN_FILE moves the token file" grep -qF "${TMP}/elsewhere" "${GC}/log"

# Opt-in: the host login, with a warning.
reset_ctr
SCOPES="repo, workflow, admin:org" host_mode gho_hosttoken
assert_eq "github auth: host opt-in logs the host token in" "gho_hosttoken" "$(cat "${GC}/ctr/gh-token" 2>/dev/null)"
assert_true "github auth: host opt-in warns" grep -q "WARNING: shared the host's gh login" "${GC}/log"
assert_true "github auth: host opt-in names risky scopes" grep -q 'scopes workflow, admin:org;' "${GC}/log"
assert_true "github auth: host token not logged" bash -c "! grep -q hosttoken '${GC}/log'"
assert_true "github auth: host token not on the command line" bash -c "! grep -q hosttoken '${GC}/docker.args'"
host_mode gho_rotated gh
assert_eq "github auth: gh is an alias of host" "gho_rotated" "$(cat "${GC}/ctr/gh-token")"
host_mode ""
assert_true "github auth: host logout removes the shared login" test ! -e "${GC}/ctr/gh-token"
assert_eq "github auth: host logout removes the rewrite" "" "$(ctr_git)"
reset_ctr
host_mode gho_hosttoken
ORCA_DOCKER_GITHUB_AUTH=host gc 'host_gh() { return 1; }; share_github_auth c1'
assert_eq "github auth: no host gh leaves the shared login alone" "gho_hosttoken" "$(cat "${GC}/ctr/gh-token")"
gc 'share_github_auth c1'
assert_true "github auth: dropping the opt-in removes the shared host login" test ! -e "${GC}/ctr/gh-token"

# The container's own login.
reset_ctr
printf 'gho_own\n' >"${GC}/ctr/gh-token"
host_mode gho_hosttoken
assert_eq "github auth: container's own login kept" "gho_own" "$(cat "${GC}/ctr/gh-token")"
assert_true "github auth: own login logged" grep -q "kept the container's own gh login" "${GC}/log"
host_mode ""
assert_eq "github auth: own login survives a host logout" "gho_own" "$(cat "${GC}/ctr/gh-token")"
reset_ctr
host_mode gho_hosttoken
printf 'gho_own\n' >"${GC}/ctr/gh-token"
gc 'share_github_auth c1'
assert_eq "github auth: own login replacing the shared one is kept" "gho_own" "$(cat "${GC}/ctr/gh-token")"
assert_eq "github auth: rewrite kept for the own login" "2" "$(ctr_git | wc -l | tr -d ' ')"

rm -f "${GC}/docker.args" "${GC}/log"
HOST_TOKEN=gho_hosttoken ORCA_DOCKER_GITHUB_AUTH=none gc 'share_github_auth c1'
assert_true "github auth: none reconciles earlier sharing" test -s "${GC}/docker.args"
assert_true "github auth: none logs no missing token file message" test ! -s "${GC}/log"

# --- reconcile_origin_remote -----------------------------------------------------
RO="${TMP}/ro"
mkdir -p "${RO}/bin" "${RO}/cbin" "${RO}/home"
RO_PATH="${TMP_PATH}/ro"
git init -q --bare "${RO}/upstream.git"
git init -q -b main "${RO}/work"
git -C "${RO}/work" config user.name test
git -C "${RO}/work" config user.email test@example.com
git -C "${RO}/work" commit --allow-empty -q -m init
git -C "${RO}/work" remote add origin "https://github.com/org/repo.git"
git -C "${RO}/work" config --local orca.originUrl "https://github.com/org/repo.git"
git -C "${RO}/work" update-ref refs/remotes/origin/main HEAD
cat >"${RO}/bin/docker" <<EOF
#!/bin/sh
[ "\$1" = exec ] || exit 1
shift 4 # exec -u <user> <name>
HOME="${RO}/home" PATH="${RO_PATH}/cbin:\$PATH" exec "\$@"
EOF
cat >"${RO}/cbin/gh" <<'EOF'
#!/bin/sh
[ "$1 $2" = "auth token" ] && [ -n "${RO_GH_TOKEN:-}" ] && { echo "$RO_GH_TOKEN"; exit 0; }
exit 1
EOF
chmod +x "${RO}/bin/docker" "${RO}/cbin/gh"
ro() { lib "PROJECT_ROOT_IN_CONTAINER='${RO}/work'; PATH='${RO_PATH}/bin':\$PATH; reconcile_origin_remote c1" 2>"${RO}/log"; }
ro
assert_eq "origin reconcile: unauthenticated github origin withheld" "" \
    "$(git -C "${RO}/work" remote)"
assert_eq "origin reconcile: saved originUrl preserved" "https://github.com/org/repo.git" \
    "$(git -C "${RO}/work" config --local --get orca.originUrl)"
assert_true "origin reconcile: origin/* refs preserved when origin withheld" \
    git -C "${RO}/work" show-ref --verify --quiet refs/remotes/origin/main
# Point saved URL at the local bare repo via url.insteadOf to simulate authorized HTTPS push,
# with token supplied via remote-env.sh as in container runtime.
mkdir -p "${RO}/home/.config/devcontainer"
printf 'export RO_GH_TOKEN=pat_ok\n' >"${RO}/home/.config/devcontainer/remote-env.sh"
git -C "${RO}/work" config --local "url.${RO}/upstream.git.insteadOf" "https://github.com/org/repo.git"
ro
assert_eq "origin reconcile: restored once push succeeds" "origin" \
    "$(git -C "${RO}/work" remote)"
assert_eq "origin reconcile: restored URL matches saved URL" "https://github.com/org/repo.git" \
    "$(git -C "${RO}/work" config --local --get remote.origin.url)"

# Simulate later token revocation/expiry after branch tracking was set to origin.
git -C "${RO}/work" config --local branch.main.remote origin
git -C "${RO}/work" config --local branch.main.pushRemote origin
git -C "${RO}/work" config --local remote.pushDefault origin
rm -f "${RO}/home/.config/devcontainer/remote-env.sh"
ro
assert_eq "origin reconcile: revoked token withholds origin again" "" \
    "$(git -C "${RO}/work" remote)"
assert_eq "origin reconcile: revoked token clears branch.main.remote" "" \
    "$(git -C "${RO}/work" config --local --get branch.main.remote || true)"
assert_eq "origin reconcile: revoked token clears branch.main.pushRemote" "" \
    "$(git -C "${RO}/work" config --local --get branch.main.pushRemote || true)"
assert_eq "origin reconcile: revoked token clears remote.pushDefault" "" \
    "$(git -C "${RO}/work" config --local --get remote.pushDefault || true)"

# --- defaults.env ----------------------------------------------------------------
printf '# repository defaults\r\nORCA_DOCKER_GITHUB_AUTH=none\r\nORCA_DOCKER_TEST_VALUE=a b=$HOME\nnot a line\n' \
    >"${REPO}/scripts/orca-vm/defaults.env"
assert_eq "defaults.env: default applied (CR stripped)" "none" "$(lib 'printf %s "$ORCA_DOCKER_GITHUB_AUTH"' 2>/dev/null)"
assert_eq "defaults.env: unknown key ignored" unset "$(lib 'printf %s "${ORCA_DOCKER_TEST_VALUE-unset}"' 2>/dev/null)"
assert_eq "defaults.env: environment wins" "host" "$(ORCA_DOCKER_GITHUB_AUTH=host lib 'printf %s "$ORCA_DOCKER_GITHUB_AUTH"' 2>/dev/null)"
assert_eq "defaults.env: empty environment value wins" "" "$(ORCA_DOCKER_GITHUB_AUTH='' lib 'printf %s "$ORCA_DOCKER_GITHUB_AUTH"' 2>/dev/null)"
assert_true "defaults.env: invalid line reported" grep -q "ignoring unsupported setting on line 4" <<<"$(lib true 2>&1)"
rm -f "${REPO}/scripts/orca-vm/defaults.env"

assert_eq "ssh_remote_host: scp form" "github.com " "$(lib 'ssh_remote_host git@github.com:o/r.git')"
assert_eq "ssh_remote_host: ssh URL with port" "h.example 2222" "$(lib 'ssh_remote_host ssh://git@h.example:2222/o/r.git')"
assert_true "ssh_remote_host: https rejected" lib_fails 'ssh_remote_host https://github.com/o/r.git'

rm -f "${GC}/docker.args"
HOST_TOKEN=gho_hosttoken gc 'share_credentials c1'
assert_true "share_credentials: no .ssh in the container" test ! -e "${GC}/ctr/.ssh"

DESTROY_SCRIPT="${REPO}/scripts/orca-vm/docker-destroy.sh"
# --- rescue_container_branches and docker-destroy.sh ---------------------------------
mkdir -p "${TMP}/rs/bin"
cat >"${TMP}/rs/bin/docker" <<'EOF'
#!/bin/sh
echo "$*" >>"${RS_LOG:-/dev/null}"
case "$1" in
    inspect) case "$*" in *Labels*) echo "${RS_REPO:-}" ;; *) echo "${RS_RUNNING:-true}" ;; esac ;;
    start) exit "${RS_START_RC:-0}" ;;
    exec) exit "${RS_EXEC_RC:-0}" ;;
    cp) case "$2" in
            *.bundle) echo bundle >"$3" ;;
            *.git) [ -z "${RS_NO_GIT:-}" ] || exit 1; mkdir -p "$3"; echo git >"$3/HEAD" ;;
        esac ;;
    rm) ;;
    *) exit 1 ;;
esac
EOF
chmod +x "${TMP}/rs/bin/docker"
rs() { lib "PATH='${TMP_PATH}/rs/bin':\$PATH; rescue_container_branches c1" 2>/dev/null; }
out="$(rs)"
assert_true "rescue: bundle saved in the state directory" \
    bash -c '[[ "$1" == "$2"/rescue/c1-*.bundle ]] && [ -f "$1" ]' _ "$out" "${TMP}/state"
out="$(RS_RUNNING=false RS_START_RC=1 rs)"
assert_true "rescue: .git copied when the container does not start" bash -c '[[ "$1" == *.git ]] && [ -f "$1/HEAD" ]' _ "$out"
if RS_EXEC_RC=1 RS_NO_GIT=1 rs >/dev/null; then fail "rescue: fails when nothing can be saved"; else pass; fi

destroy() {
    printf '{"recipeResult":{"userData":{"resourceId":"c1"}}}' \
        | HOME="${TMP}/home" PATH="${TMP_PATH}/rs/bin:${PATH}" ORCA_DOCKER_STATE_DIR="${TMP}/state" \
            ORCA_DOCKER_SKIP_LOCAL_ENV=1 RS_REPO="$REPO" RS_LOG="${TMP}/rs/docker.log" RS_RUNNING=false RS_START_RC=1 \
            "$DESTROY_SCRIPT" >/dev/null 2>"${TMP}/rs/destroy.log"
}
rm -f "${TMP}/rs/docker.log"
if RS_NO_GIT=1 destroy; then fail "destroy: fails when the branches cannot be saved"; else pass; fi
assert_true "destroy: container kept when the branches cannot be saved" bash -c "! grep -q '^rm ' '${TMP}/rs/docker.log'"
rm -f "${TMP}/rs/docker.log"
assert_true "destroy: removes the container once the branches are saved" destroy
assert_true "destroy: rescue path logged" grep -q 'saved them to .*/rescue/c1-' "${TMP}/rs/destroy.log"
assert_true "destroy: container removed" grep -q '^rm -f c1' "${TMP}/rs/docker.log"

echo "${passes} passed, ${failures} failed"
[ "$failures" -eq 0 ]
